import subprocess
import os
import glob
import time
def task_func(test_dir):
    execution_times = {}
    files = glob.glob(os.path.join(test_dir, "*.py"))
    for file_path in files:
        start_time = time.time()
        try:
            subprocess.run([sys.executable, file_path], check=True, capture_output=True)
            end_time = time.time()
            execution_times[os.path.basename(file_path)] = end_time - start_time
        except subprocess.CalledProcessError:
            execution_times[os.path.basename(file_path)] = -1.0
    return execution_times

