import subprocess
import time
import json
import platform
import datetime
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero.")

    data = []
    end_time = time.time() + duration

    is_windows = platform.system() == "Windows"

    while time.time() < end_time:
        try:
            if is_windows:
                output = subprocess.check_output("wmic cpu get loadpercentage", shell=True).decode()
                cpu_usage = int(output.split('\n')[1].strip())
            else:
                output = subprocess.check_output("top -bn1 | grep 'Cpu(s)'", shell=True).decode()
                cpu_idle = float(output.split(',')[3].split()[0])
                cpu_usage = 100.0 - cpu_idle

            data.append({
                "timestamp": datetime.datetime.now().isoformat(),
                "cpu_usage": cpu_usage
            })
        except Exception:
            pass

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

